def test_search_window_includes_the_366th_day_after_the_nominal_day():
    nominal = date(2024, 1, 1)
    closed = {nominal + timedelta(days=days) for days in range(366)}

    [visit] = plan_visits(
        first_day=nominal,
        offsets_months=[0],
        hour=9,
        minute=0,
        timezone="America/New_York",
        closed_days=closed,
    )

    assert visit["local"] == "2025-01-01T09:00:00-05:00"


def test_booking_sequential_calls_contend_for_slots():
    capacity = {date(2024, 7, 1): 2}

    first = book(capacity)
    assert capacity == {date(2024, 7, 1): 1}
    second = book(capacity)
    assert capacity == {date(2024, 7, 1): 0}
    third = book(capacity)

    assert first == second == [
        {
            "offset_months": 0,
            "local": "2024-07-01T09:00:00-04:00",
            "utc": "2024-07-01T13:00:00Z",
        }
    ]
    assert third[0]["local"] == "2024-07-02T09:00:00-04:00"
    # The unlisted overflow day stays unconstrained and is never inserted.
    assert capacity == {date(2024, 7, 1): 0}


def test_booking_decrements_once_per_visit_sharing_a_day():
    closed = {date(2024, 1, 31)} | {date(2024, 2, day) for day in range(1, 29)}
    capacity = {date(2024, 2, 29): 2, date(2024, 3, 1): 5}

    visits = book(
        capacity,
        first_day=date(2024, 1, 31),
        offsets_months=[0, 1],
        closed_days=closed,
    )

    assert [visit["local"][:10] for visit in visits] == ["2024-02-29", "2024-02-29"]
    assert capacity == {date(2024, 2, 29): 0, date(2024, 3, 1): 5}


def test_booking_rolls_back_when_a_later_visit_cannot_be_scheduled():
    capacity = {date(2024, 1, 1): 2}
    book(capacity, first_day=date(2024, 1, 1))
    assert capacity == {date(2024, 1, 1): 1}

    closed = {date(2024, 2, 1) + timedelta(days=days) for days in range(367)}
    original_closed = closed.copy()
    with pytest.raises(ValueError, match="UNSCHEDULABLE"):
        book(
            capacity,
            first_day=date(2024, 1, 1),
            offsets_months=[0, 1],
            closed_days=closed,
        )

    # The failed call reserved nothing; the earlier booking stays committed.
    assert capacity == {date(2024, 1, 1): 1}
    assert closed == original_closed


def test_booking_ineligible_subject_reports_ordered_reasons_before_planning():
    subject = make_subject()
    subject.update(flags=["PRIOR"], labs={"A": 0, "Z": 15})
    capacity = {date(2024, 7, 1): 1}

    with pytest.raises(ValueError) as error:
        # The invalid zone shows that eligibility is checked before planning.
        book(capacity, subject=subject, timezone="Not/A_Real_Zone")

    assert str(error.value) == "INELIGIBLE:EXCLUSION_PRIOR,LAB_A_LOW"
    assert capacity == {date(2024, 7, 1): 1}


def test_booking_planning_errors_leave_capacity_unchanged():
    capacity = {date(2024, 7, 1): 1}

    with pytest.raises(ValueError, match="INVALID_TIMEZONE"):
        book(capacity, timezone="Not/A_Real_Zone")
    with pytest.raises(ValueError, match="DUPLICATE_OFFSET"):
        book(capacity, offsets_months=[0, 0])
    with pytest.raises(TypeError):
        book(None)

    assert capacity == {date(2024, 7, 1): 1}


def test_booking_preserves_month_end_plan_and_does_not_mutate_inputs():
    subject = make_subject()
    protocol = make_protocol()
    subject_snapshot = deepcopy(subject)
    protocol_snapshot = deepcopy(protocol)
    capacity = {date(2024, 2, 29): 1, date(2024, 3, 31): 3, date(2030, 1, 1): 0}
    arguments = {
        "first_day": date(2024, 1, 31),
        "offsets_months": [1, 2, 12],
        "hour": 9,
        "minute": 5,
        "timezone": "America/New_York",
    }
    expected = plan_visits(capacity=dict(capacity), **arguments)

    visits = book(capacity, subject=subject, protocol=protocol, **arguments)

    assert visits == expected
    assert [visit["local"] for visit in visits] == [
        "2024-02-29T09:05:00-05:00",
        "2024-03-31T09:05:00-04:00",
        "2025-01-31T09:05:00-05:00",
    ]
    assert capacity == {
        date(2024, 2, 29): 0,
        date(2024, 3, 31): 2,
        date(2030, 1, 1): 0,
    }
    assert subject == subject_snapshot
    assert protocol == protocol_snapshot


def test_booking_preserves_dst_handling_and_wall_time_when_rescheduled():
    capacity = {date(2024, 3, 10): 1}
    spring = {"first_day": date(2024, 3, 10), "hour": 2, "minute": 30}

    in_gap = book(capacity, **spring)
    moved = book(capacity, **spring)

    assert in_gap == [
        {
            "offset_months": 0,
            "local": "2024-03-10T03:30:00-04:00",
            "utc": "2024-03-10T07:30:00Z",
        }
    ]
    # The next day has no gap, so the original 02:30 wall time is restored.
    assert moved == [
        {
            "offset_months": 0,
            "local": "2024-03-11T02:30:00-04:00",
            "utc": "2024-03-11T06:30:00Z",
        }
    ]
    assert capacity == {date(2024, 3, 10): 0}

    fall_capacity = {date(2024, 11, 3): 1}
    [ambiguous] = book(
        fall_capacity, first_day=date(2024, 11, 3), hour=1, minute=30
    )
    assert ambiguous["local"] == "2024-11-03T01:30:00-04:00"
    assert ambiguous["utc"] == "2024-11-03T05:30:00Z"
    assert fall_capacity == {date(2024, 11, 3): 0}

    paris_capacity = {date(2024, 3, 31): 1}
    [paris] = book(
        paris_capacity,
        first_day=date(2024, 3, 31),
        hour=2,
        minute=30,
        timezone="Europe/Paris",
    )
    assert paris["local"] == "2024-03-31T03:30:00+02:00"
    assert paris["utc"] == "2024-03-31T01:30:00Z"
    assert paris_capacity == {date(2024, 3, 31): 0}
